using Microsoft.AspNetCore.Mvc;using SonadaBeds.Web.Data;using SonadaBeds.Web.Models;
namespace SonadaBeds.Web.Controllers;public class CheckoutController(SonadaDbContext db,CartService cart):Controller{[HttpGet]public IActionResult Index()=>View();[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> PlaceOrder(string email,string shippingAddress){if(!cart.Items.Any())return RedirectToAction("Index","Cart");var order=new Order{OrderNumber=$"SB-{DateTime.UtcNow:yyyyMMddHHmmssfff}",Email=email,ShippingAddress=shippingAddress,Subtotal=cart.Subtotal,Delivery=cart.Subtotal>=750?0:49,Total=cart.Subtotal+(cart.Subtotal>=750?0:49)};foreach(var i in cart.Items)order.Items.Add(new OrderItem{ProductName=i.ProductName,UnitPrice=i.UnitPrice,Quantity=i.Quantity,ConfigurationJson=i.ConfigurationJson});db.Orders.Add(order);await db.SaveChangesAsync();cart.Clear();return View("Confirmation",order);}}
